#[derive(Debug)]
pub enum AccountError { InvalidAmount, BelowFloor }

pub struct Account { balance: u64, floor: u64 }

impl Account {
    pub fn withdraw(&mut self, amount: u64) -> Result<(), AccountError> {
        if amount == 0 {
            return Err(AccountError::InvalidAmount);
        }
        let Some(next_balance) = self.balance.checked_sub(amount) else {
            return Err(AccountError::BelowFloor);
        };
        if next_balance < self.floor {
            return Err(AccountError::BelowFloor);
        }
        self.balance = next_balance;
        assert!(self.balance >= self.floor, "invariant: {} < {}", self.balance, self.floor);
        Ok(())
    }
}
